// 各イベントに一意のslugを付与（詳細ページのルーティングに使用）
ERAS.forEach((era) => {
  era.events.forEach((ev, i) => {
    ev.slug = `${era.id}--${i}`;
  });
});

export function findEventBySlug(slug) {
  for (const era of ERAS) {
    const event = era.events.find((ev) => ev.slug === slug);
    if (event) return { event, era };
  }
  return null;
}

// 全イベントを年表順に並べたフラットな配列（前後イベントの取得に使用）
const FLAT_EVENTS = ERAS.flatMap((era) => era.events.map((event) => ({ event, era })));

// 指定したslugの次のイベントを返す（最後のイベントの場合はnull）
export function getNextEvent(slug) {
  const idx = FLAT_EVENTS.findIndex((item) => item.event.slug === slug);
  if (idx === -1 || idx === FLAT_EVENTS.length - 1) return null;
  return FLAT_EVENTS[idx + 1];
}

// ルビ記法 {{漢字|ふりがな}} を除去し、素のテキストを返す（メタデータ用）
export function stripRuby(text) {
  if (!text) return text;
  return text.replace(/\{\{(.+?)\|(.+?)\}\}/g, "$1");
}

